create table public.cart_items (id uuid primary key default gen_random_uuid(), store_id uuid not null, cart_id uuid not null, variant_id uuid not null, quantity integer not null check(quantity between 1 and 1000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,cart_id) references public.carts(store_id,id) on delete cascade, foreign key(store_id,variant_id) references public.product_variants(store_id,id) on delete cascade, unique(cart_id,variant_id));
